using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;

namespace ContosoUniversity.Tests
{
    public static class TestHelpers
    {
        public static SchoolContext CreateInMemoryContext(string dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;
            return new SchoolContext(options);
        }

        public static void SeedStudents(SchoolContext context)
        {
            context.Students.AddRange(
                new Student { ID = 1, FirstMidName = "Carson", LastName = "Alexander", EnrollmentDate = DateTime.Parse("2010-09-01") },
                new Student { ID = 2, FirstMidName = "Meredith", LastName = "Alonso", EnrollmentDate = DateTime.Parse("2012-09-01") },
                new Student { ID = 3, FirstMidName = "Arturo", LastName = "Anand", EnrollmentDate = DateTime.Parse("2013-09-01") }
            );
            context.SaveChanges();
        }

        public static void SeedDepartments(SchoolContext context)
        {
            context.Departments.AddRange(
                new Department { DepartmentID = 1, Name = "English", Budget = 350000, StartDate = DateTime.Parse("2007-09-01") },
                new Department { DepartmentID = 2, Name = "Mathematics", Budget = 100000, StartDate = DateTime.Parse("2007-09-01") }
            );
            context.SaveChanges();
        }

        public static void SeedInstructors(SchoolContext context)
        {
            context.Instructors.AddRange(
                new Instructor { ID = 10, FirstMidName = "Kim", LastName = "Abercrombie", HireDate = DateTime.Parse("1995-03-11"), CourseAssignments = new List<CourseAssignment>() },
                new Instructor { ID = 11, FirstMidName = "Fadi", LastName = "Fakhouri", HireDate = DateTime.Parse("2002-07-06"), CourseAssignments = new List<CourseAssignment>() }
            );
            context.SaveChanges();
        }

        public static void SeedCourses(SchoolContext context)
        {
            if (context.Departments.Find(1) == null)
                SeedDepartments(context);

            context.Courses.AddRange(
                new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = 1 },
                new Course { CourseID = 4022, Title = "Microeconomics", Credits = 3, DepartmentID = 2 }
            );
            context.SaveChanges();
        }

        public static void SeedAll(SchoolContext context)
        {
            SeedInstructors(context);
            SeedDepartments(context);
            SeedCourses(context);
            SeedStudents(context);
        }
    }
}

using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests
    {
        [Fact]
        public void SendNotification_EnqueuesNotification()
        {
            using var service = new NotificationService();

            service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");

            var notification = service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("Admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
            Assert.Contains("John Doe", notification.Message);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesIdInMessage()
        {
            using var service = new NotificationService();

            service.SendNotification("Course", "42", EntityOperation.UPDATE, "System");

            var notification = service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("ID: 42", notification.Message);
            Assert.Contains("updated", notification.Message);
        }

        [Fact]
        public void SendNotification_DeleteOperation_GeneratesCorrectMessage()
        {
            using var service = new NotificationService();

            service.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE);

            var notification = service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("deleted", notification.Message);
            Assert.Contains("Engineering", notification.Message);
        }

        [Fact]
        public void SendNotification_DefaultUser_IsSystem()
        {
            using var service = new NotificationService();

            service.SendNotification("Student", "1", EntityOperation.CREATE);

            var notification = service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            using var service = new NotificationService();

            // Drain any existing notifications from static queue
            while (service.ReceiveNotification() != null) { }

            var notification = service.ReceiveNotification();
            Assert.Null(notification);
        }

        [Fact]
        public void SendNotification_MultipleNotifications_ReceivedInOrder()
        {
            using var service = new NotificationService();

            // Drain existing
            while (service.ReceiveNotification() != null) { }

            service.SendNotification("Student", "1", "First", EntityOperation.CREATE);
            service.SendNotification("Student", "2", "Second", EntityOperation.UPDATE);
            service.SendNotification("Student", "3", "Third", EntityOperation.DELETE);

            var n1 = service.ReceiveNotification();
            var n2 = service.ReceiveNotification();
            var n3 = service.ReceiveNotification();

            Assert.Equal("1", n1.EntityId);
            Assert.Equal("2", n2.EntityId);
            Assert.Equal("3", n3.EntityId);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            using var service = new NotificationService();

            // MarkAsRead is a no-op for in-memory, just verify no exception
            var exception = Record.Exception(() => service.MarkAsRead(999));
            Assert.Null(exception);
        }

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            var service = new NotificationService();
            var exception = Record.Exception(() => service.Dispose());
            Assert.Null(exception);
        }

        [Fact]
        public void SendNotification_CreateOperation_MessageContainsCreated()
        {
            using var service = new NotificationService();

            service.SendNotification("Instructor", "7", "Jane Smith", EntityOperation.CREATE);

            var notification = service.ReceiveNotification();
            Assert.Contains("created", notification.Message);
            Assert.Contains("Jane Smith", notification.Message);
        }

        [Fact]
        public void SendNotification_SetsCreatedAtToNow()
        {
            using var service = new NotificationService();
            var before = DateTime.Now.AddSeconds(-1);

            service.SendNotification("Student", "1", EntityOperation.CREATE);

            var notification = service.ReceiveNotification();
            Assert.True(notification.CreatedAt >= before);
            Assert.True(notification.CreatedAt <= DateTime.Now.AddSeconds(1));
        }
    }
}

