using ContosoUniversity.Controllers;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests
    {
        [Fact]
        public void Index_ReturnsViewResult_WithStudentsList()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedStudents(context);
            using var controller = new StudentsController(context);

            var result = controller.Index(null, null, null, null) as ViewResult;

            Assert.NotNull(result);
            var model = result.Model as PaginatedList<Student>;
            Assert.NotNull(model);
            Assert.Equal(3, model.Count);
        }

        [Fact]
        public void Index_WithSearchString_FiltersResults()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedStudents(context);
            using var controller = new StudentsController(context);

            var result = controller.Index(null, null, "Alexander", null) as ViewResult;

            var model = result.Model as PaginatedList<Student>;
            Assert.Single(model);
            Assert.Equal("Alexander", model[0].LastName);
        }

        [Fact]
        public void Index_WithNameDescSort_SortsDescending()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedStudents(context);
            using var controller = new StudentsController(context);

            var result = controller.Index("name_desc", null, null, null) as ViewResult;

            var model = result.Model as PaginatedList<Student>;
            Assert.Equal("Anand", model[0].LastName);
        }

        [Fact]
        public void Index_WithDateSort_SortsByDateAscending()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedStudents(context);
            using var controller = new StudentsController(context);

            var result = controller.Index("Date", null, null, null) as ViewResult;

            var model = result.Model as PaginatedList<Student>;
            Assert.Equal("Alexander", model[0].LastName); // 2010
        }

        [Fact]
        public void Index_WithDateDescSort_SortsByDateDescending()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedStudents(context);
            using var controller = new StudentsController(context);

            var result = controller.Index("date_desc", null, null, null) as ViewResult;

            var model = result.Model as PaginatedList<Student>;
            Assert.Equal("Anand", model[0].LastName); // 2013
        }

        [Fact]
        public void Index_SearchResetsPage()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedStudents(context);
            using var controller = new StudentsController(context);

            // When searchString is not null, page should reset to 1
            var result = controller.Index(null, null, "A", 5) as ViewResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void Index_NullSearchString_UsesCurrentFilter()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedStudents(context);
            using var controller = new StudentsController(context);

            var result = controller.Index(null, "Alexander", null, null) as ViewResult;

            var model = result.Model as PaginatedList<Student>;
            Assert.Single(model);
        }

        [Fact]
        public void Details_WithValidId_ReturnsStudent()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedStudents(context);
            using var controller = new StudentsController(context);

            var result = controller.Details(1) as ViewResult;

            Assert.NotNull(result);
            var student = result.Model as Student;
            Assert.Equal("Carson", student.FirstMidName);
        }

        [Fact]
        public void Details_WithNullId_ReturnsBadRequest()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            using var controller = new StudentsController(context);

            var result = controller.Details(null) as StatusCodeResult;

            Assert.NotNull(result);
            Assert.Equal(400, result.StatusCode);
        }

        [Fact]
        public void Create_GET_ReturnsViewWithStudent()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            using var controller = new StudentsController(context);

            var result = controller.Create() as ViewResult;

            Assert.NotNull(result);
            var student = result.Model as Student;
            Assert.NotNull(student);
            Assert.Equal(DateTime.Today, student.EnrollmentDate);
        }

        [Fact]
        public void Create_POST_ValidStudent_RedirectsToIndex()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            using var controller = new StudentsController(context);

            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = new DateTime(2020, 9, 1)
            };

            var result = controller.Create(student) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Single(context.Students);
        }

        [Fact]
        public void Create_POST_InvalidEnrollmentDate_ReturnsView()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            using var controller = new StudentsController(context);

            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = DateTime.MinValue
            };

            var result = controller.Create(student) as ViewResult;

            Assert.NotNull(result);
            Assert.False(controller.ModelState.IsValid);
        }

        [Fact]
        public void Create_POST_DateOutOfRange_ReturnsView()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            using var controller = new StudentsController(context);

            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = new DateTime(1752, 1, 1)
            };

            var result = controller.Create(student) as ViewResult;

            Assert.NotNull(result);
            Assert.False(controller.ModelState.IsValid);
        }

        [Fact]
        public void Create_POST_InvalidModelState_ReturnsView()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            using var controller = new StudentsController(context);
            controller.ModelState.AddModelError("LastName", "Required");

            var student = new Student
            {
                FirstMidName = "Test",
                EnrollmentDate = new DateTime(2020, 9, 1)
            };

            var result = controller.Create(student) as ViewResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void Edit_GET_WithValidId_ReturnsView()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedStudents(context);
            using var controller = new StudentsController(context);

            var result = controller.Edit(1) as ViewResult;

            Assert.NotNull(result);
            var student = result.Model as Student;
            Assert.Equal("Carson", student.FirstMidName);
        }

        [Fact]
        public void Edit_GET_WithNullId_ReturnsBadRequest()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            using var controller = new StudentsController(context);

            var result = controller.Edit((int?)null) as StatusCodeResult;

            Assert.Equal(400, result.StatusCode);
        }

        [Fact]
        public void Edit_GET_WithInvalidId_ReturnsNotFound()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            using var controller = new StudentsController(context);

            var result = controller.Edit(999) as NotFoundResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void Edit_POST_ValidStudent_RedirectsToIndex()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedStudents(context);

            // Detach existing entity to avoid tracking conflict
            var existing = context.Students.Find(1);
            context.Entry(existing).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            using var controller = new StudentsController(context);

            var student = new Student
            {
                ID = 1,
                FirstMidName = "Updated",
                LastName = "Alexander",
                EnrollmentDate = new DateTime(2010, 9, 1)
            };

            var result = controller.Edit(student) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
        }

        [Fact]
        public void Edit_POST_InvalidEnrollmentDate_ReturnsView()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedStudents(context);
            using var controller = new StudentsController(context);

            var student = new Student
            {
                ID = 1,
                FirstMidName = "Carson",
                LastName = "Alexander",
                EnrollmentDate = DateTime.MinValue
            };

            var result = controller.Edit(student) as ViewResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void Delete_GET_WithValidId_ReturnsView()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedStudents(context);
            using var controller = new StudentsController(context);

            var result = controller.Delete(1) as ViewResult;

            Assert.NotNull(result);
            var student = result.Model as Student;
            Assert.Equal("Carson", student.FirstMidName);
        }

        [Fact]
        public void Delete_GET_WithNullId_ReturnsBadRequest()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            using var controller = new StudentsController(context);

            var result = controller.Delete(null) as StatusCodeResult;

            Assert.Equal(400, result.StatusCode);
        }

        [Fact]
        public void Delete_GET_WithInvalidId_ReturnsNotFound()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            using var controller = new StudentsController(context);

            var result = controller.Delete(999) as NotFoundResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void DeleteConfirmed_RemovesStudent()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedStudents(context);
            using var controller = new StudentsController(context);

            var result = controller.DeleteConfirmed(1) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Equal(2, context.Students.Count());
        }

        [Fact]
        public void Index_DefaultSort_SortsByLastNameAscending()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedStudents(context);
            using var controller = new StudentsController(context);

            var result = controller.Index(null, null, null, null) as ViewResult;

            var model = result.Model as PaginatedList<Student>;
            Assert.Equal("Alexander", model[0].LastName);
            Assert.Equal("Alonso", model[1].LastName);
            Assert.Equal("Anand", model[2].LastName);
        }

        [Fact]
        public void Index_SetsViewBagProperties()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedStudents(context);
            using var controller = new StudentsController(context);

            var result = controller.Index("Date", null, "test", null) as ViewResult;

            Assert.Equal("Date", controller.ViewBag.CurrentSort);
            Assert.Equal("date_desc", controller.ViewBag.DateSortParm);
            Assert.Equal("test", controller.ViewBag.CurrentFilter);
        }
    }
}

using ContosoUniversity.Controllers;
