        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedCourses(context);
            using var controller = CreateController(context);

            var result = controller.Details(1050) as ViewResult;

            Assert.NotNull(result);
            var course = result.Model as Course;
            Assert.Equal("Chemistry", course.Title);
        }

