        public void Create_POST_InvalidFileExtension_ReturnsViewWithError()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedDepartments(context);
            using var controller = CreateController(context);

            var file = new Mock<IFormFile>();
            file.Setup(f => f.FileName).Returns("test.exe");
            file.Setup(f => f.Length).Returns(1024);

            var course = new Course { CourseID = 9999, Title = "Test", Credits = 3, DepartmentID = 1 };

