                CourseAssignments = new List<CourseAssignment>(),
                OfficeAssignment = new OfficeAssignment { InstructorID = 11, Location = "Smith 17" }
            };

            context.Instructors.AddRange(instructor1, instructor2);
            context.SaveChanges();

            context.Departments.Add(new Department { DepartmentID = 1, Name = "English", Budget = 350000, StartDate = DateTime.Parse("2007-09-01") });
            context.SaveChanges();

            context.Courses.Add(new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = 1 });
            context.Courses.Add(new Course { CourseID = 2021, Title = "Composition", Credits = 3, DepartmentID = 1 });
            context.SaveChanges();

            context.CourseAssignments.Add(new CourseAssignment { InstructorID = 10, CourseID = 1050 });
            context.SaveChanges();

            return context;
        }

        [Fact]
        public void Index_NoParams_ReturnsAllInstructors()
        {
