using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Moq;
using System.IO;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class CoursesControllerTests
    {
        private CoursesController CreateController(SchoolContext context)
        {
            var env = new Mock<IWebHostEnvironment>();
            env.Setup(e => e.WebRootPath).Returns(Path.GetTempPath());
            env.Setup(e => e.ContentRootPath).Returns(Path.GetTempPath());
            var logger = new Mock<ILogger<CoursesController>>();
            return new CoursesController(context, env.Object, logger.Object);
        }

        [Fact]
        public void Index_ReturnsViewWithCourses()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedCourses(context);
            using var controller = CreateController(context);

            var result = controller.Index() as ViewResult;

            Assert.NotNull(result);
            var model = result.Model as System.Collections.Generic.List<Course>;
            Assert.Equal(2, model.Count);
        }

        [Fact]
        public void Details_WithValidId_ReturnsCourse()
        {
            using var context = TestHelpers.CreateInMemoryContext();
