using ContosoUniversity.Controllers;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class DepartmentsControllerTests
    {
        [Fact]
        public void Index_ReturnsViewWithDepartments()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedDepartments(context);
            using var controller = new DepartmentsController(context);

            var result = controller.Index() as ViewResult;

            Assert.NotNull(result);
            var model = result.Model as System.Collections.Generic.List<Department>;
            Assert.Equal(2, model.Count);
        }

        [Fact]
        public void Details_WithValidId_ReturnsDepartment()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedDepartments(context);
            using var controller = new DepartmentsController(context);

            var result = controller.Details(1) as ViewResult;

            Assert.NotNull(result);
            var dept = result.Model as Department;
            Assert.Equal("English", dept.Name);
        }

        [Fact]
        public void Details_WithNullId_ReturnsBadRequest()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            using var controller = new DepartmentsController(context);

            var result = controller.Details(null) as StatusCodeResult;

            Assert.Equal(400, result.StatusCode);
        }

        [Fact]
        public void Details_WithInvalidId_ReturnsNotFound()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            using var controller = new DepartmentsController(context);

            var result = controller.Details(999) as NotFoundResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void Create_GET_ReturnsView()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedInstructors(context);
            using var controller = new DepartmentsController(context);

            var result = controller.Create() as ViewResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void Create_POST_ValidDepartment_RedirectsToIndex()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedInstructors(context);
            using var controller = new DepartmentsController(context);

            var department = new Department
            {
                Name = "Science",
                Budget = 200000,
                StartDate = new DateTime(2020, 1, 1),
                InstructorID = 10
            };

            var result = controller.Create(department) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Equal(1, context.Departments.Count());
        }

        [Fact]
        public void Create_POST_InvalidModel_ReturnsView()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedInstructors(context);
            using var controller = new DepartmentsController(context);
            controller.ModelState.AddModelError("Name", "Required");

            var department = new Department();

            var result = controller.Create(department) as ViewResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void Edit_GET_WithValidId_ReturnsView()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedInstructors(context);
            TestHelpers.SeedDepartments(context);
            using var controller = new DepartmentsController(context);

            var result = controller.Edit(1) as ViewResult;

            Assert.NotNull(result);
            var dept = result.Model as Department;
            Assert.Equal("English", dept.Name);
        }

        [Fact]
        public void Edit_GET_WithNullId_ReturnsBadRequest()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            using var controller = new DepartmentsController(context);

            var result = controller.Edit((int?)null) as StatusCodeResult;

            Assert.Equal(400, result.StatusCode);
        }

        [Fact]
        public void Edit_GET_WithInvalidId_ReturnsNotFound()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            using var controller = new DepartmentsController(context);

            var result = controller.Edit(999) as NotFoundResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void Edit_POST_ValidDepartment_RedirectsToIndex()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedInstructors(context);
            TestHelpers.SeedDepartments(context);

            var existing = context.Departments.Find(1);
            context.Entry(existing).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            using var controller = new DepartmentsController(context);

            var department = new Department
            {
                DepartmentID = 1,
                Name = "Updated English",
                Budget = 400000,
                StartDate = new DateTime(2007, 9, 1),
                InstructorID = 10
            };

            var result = controller.Edit(department) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
        }

        [Fact]
        public void Edit_POST_InvalidModel_ReturnsView()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedInstructors(context);
            using var controller = new DepartmentsController(context);
            controller.ModelState.AddModelError("Name", "Required");

            var department = new Department { DepartmentID = 1 };

            var result = controller.Edit(department) as ViewResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void Delete_GET_WithValidId_ReturnsView()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedDepartments(context);
            using var controller = new DepartmentsController(context);

            var result = controller.Delete(1) as ViewResult;

            Assert.NotNull(result);
            var dept = result.Model as Department;
            Assert.Equal("English", dept.Name);
        }

        [Fact]
        public void Delete_GET_WithNullId_ReturnsBadRequest()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            using var controller = new DepartmentsController(context);

            var result = controller.Delete(null) as StatusCodeResult;

            Assert.Equal(400, result.StatusCode);
        }

        [Fact]
        public void Delete_GET_WithInvalidId_ReturnsNotFound()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            using var controller = new DepartmentsController(context);

            var result = controller.Delete(999) as NotFoundResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void DeleteConfirmed_RemovesDepartment()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedDepartments(context);
            using var controller = new DepartmentsController(context);

            var result = controller.DeleteConfirmed(1) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Null(context.Departments.Find(1));
        }
    }
}

