using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class InstructorsControllerTests
    {
        private SchoolContext CreateSeededContext()
        {
            var context = TestHelpers.CreateInMemoryContext();

            var instructor1 = new Instructor
            {
                ID = 10,
                FirstMidName = "Kim",
                LastName = "Abercrombie",
                HireDate = DateTime.Parse("1995-03-11"),
                CourseAssignments = new List<CourseAssignment>()
            };
            var instructor2 = new Instructor
            {
                ID = 11,
                FirstMidName = "Fadi",
                LastName = "Fakhouri",
                HireDate = DateTime.Parse("2002-07-06"),
                CourseAssignments = new List<CourseAssignment>(),
                OfficeAssignment = new OfficeAssignment { InstructorID = 11, Location = "Smith 17" }
            };

            context.Instructors.AddRange(instructor1, instructor2);
            context.SaveChanges();

            context.Departments.Add(new Department { DepartmentID = 1, Name = "English", Budget = 350000, StartDate = DateTime.Parse("2007-09-01") });
            context.SaveChanges();

            context.Courses.Add(new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = 1 });
            context.Courses.Add(new Course { CourseID = 2021, Title = "Composition", Credits = 3, DepartmentID = 1 });
            context.SaveChanges();

            context.CourseAssignments.Add(new CourseAssignment { InstructorID = 10, CourseID = 1050 });
            context.SaveChanges();

            return context;
        }

        [Fact]
        public void Index_NoParams_ReturnsAllInstructors()
        {
            using var context = CreateSeededContext();
            using var controller = new InstructorsController(context);

            var result = controller.Index(null, null) as ViewResult;

            Assert.NotNull(result);
            var model = result.Model as Models.SchoolViewModels.InstructorIndexData;
            Assert.NotNull(model);
            Assert.Equal(2, model.Instructors.Count());
        }

        [Fact]
        public void Index_WithInstructorId_PopulatesCourses()
        {
            using var context = CreateSeededContext();
            using var controller = new InstructorsController(context);

            var result = controller.Index(10, null) as ViewResult;

            var model = result.Model as Models.SchoolViewModels.InstructorIndexData;
            Assert.NotNull(model.Courses);
            Assert.Single(model.Courses);
            Assert.Equal("Chemistry", model.Courses.First().Title);
        }

        [Fact]
        public void Details_WithValidId_ReturnsInstructor()
        {
            using var context = CreateSeededContext();
            using var controller = new InstructorsController(context);

            var result = controller.Details(10) as ViewResult;

            Assert.NotNull(result);
            var instructor = result.Model as Instructor;
            Assert.Equal("Kim", instructor.FirstMidName);
        }

        [Fact]
        public void Details_WithNullId_ReturnsBadRequest()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            using var controller = new InstructorsController(context);

            var result = controller.Details(null) as StatusCodeResult;

            Assert.Equal(400, result.StatusCode);
        }

        [Fact]
        public void Details_WithInvalidId_ReturnsNotFound()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            using var controller = new InstructorsController(context);

            var result = controller.Details(999) as NotFoundResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void Create_GET_ReturnsView()
        {
            using var context = CreateSeededContext();
            using var controller = new InstructorsController(context);

            var result = controller.Create() as ViewResult;

            Assert.NotNull(result);
            var model = result.Model as Instructor;
            Assert.NotNull(model);
            Assert.NotNull(model.CourseAssignments);
        }

        [Fact]
        public void Create_POST_ValidInstructor_RedirectsToIndex()
        {
            using var context = CreateSeededContext();
            using var controller = new InstructorsController(context);

            var instructor = new Instructor
            {
                FirstMidName = "New",
                LastName = "Instructor",
                HireDate = new DateTime(2020, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = controller.Create(instructor, null) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
        }

        [Fact]
        public void Create_POST_WithSelectedCourses_AssignsCourses()
        {
            using var context = CreateSeededContext();
            using var controller = new InstructorsController(context);

            var instructor = new Instructor
            {
                FirstMidName = "New",
                LastName = "Instructor",
                HireDate = new DateTime(2020, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = controller.Create(instructor, new[] { "1050", "2021" }) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            var saved = context.Instructors.Include(i => i.CourseAssignments).OrderBy(i => i.ID).Last();
            Assert.Equal(2, saved.CourseAssignments.Count);
        }

        [Fact]
        public void Create_POST_InvalidModel_ReturnsView()
        {
            using var context = CreateSeededContext();
            using var controller = new InstructorsController(context);
            controller.ModelState.AddModelError("LastName", "Required");

            var instructor = new Instructor
            {
                FirstMidName = "Test",
                HireDate = new DateTime(2020, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = controller.Create(instructor, null) as ViewResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void Edit_GET_WithValidId_ReturnsView()
        {
            using var context = CreateSeededContext();
            using var controller = new InstructorsController(context);

            var result = controller.Edit((int?)10) as ViewResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void Edit_GET_WithNullId_ReturnsBadRequest()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            using var controller = new InstructorsController(context);

            var result = controller.Edit((int?)null) as StatusCodeResult;

            Assert.Equal(400, result.StatusCode);
        }

        [Fact]
        public void Delete_GET_WithValidId_ReturnsView()
        {
            using var context = CreateSeededContext();
            using var controller = new InstructorsController(context);

            var result = controller.Delete(10) as ViewResult;

            Assert.NotNull(result);
            var instructor = result.Model as Instructor;
            Assert.Equal("Kim", instructor.FirstMidName);
        }

        [Fact]
        public void Delete_GET_WithNullId_ReturnsBadRequest()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            using var controller = new InstructorsController(context);

            var result = controller.Delete(null) as StatusCodeResult;

            Assert.Equal(400, result.StatusCode);
        }

        [Fact]
        public void Delete_GET_WithInvalidId_ReturnsNotFound()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            using var controller = new InstructorsController(context);

            var result = controller.Delete(999) as NotFoundResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void DeleteConfirmed_RemovesInstructor()
        {
            using var context = CreateSeededContext();
            using var controller = new InstructorsController(context);

            var result = controller.DeleteConfirmed(10) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Null(context.Instructors.Find(10));
        }

        [Fact]
        public void DeleteConfirmed_ClearsDepartmentAdministrator()
        {
            using var context = CreateSeededContext();
            var dept = context.Departments.Find(1);
            dept.InstructorID = 10;
            context.SaveChanges();

            using var controller = new InstructorsController(context);

            controller.DeleteConfirmed(10);

            var updatedDept = context.Departments.Find(1);
            Assert.Null(updatedDept.InstructorID);
        }
    }
}

