using ContosoUniversity.Controllers;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests
    {
        [Fact]
        public void GetNotifications_ReturnsJsonResult()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            using var controller = new NotificationsController(context);

            var result = controller.GetNotifications();

            Assert.NotNull(result);
            Assert.IsType<JsonResult>(result);
        }

        [Fact]
        public void MarkAsRead_ReturnsJsonResult()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            using var controller = new NotificationsController(context);

            var result = controller.MarkAsRead(1);

            Assert.NotNull(result);
            Assert.IsType<JsonResult>(result);
        }

        [Fact]
        public void Index_ReturnsViewResult()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            using var controller = new NotificationsController(context);

            var result = controller.Index() as ViewResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void GetNotifications_LimitsToTenNotifications()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            using var controller = new NotificationsController(context);

            var service = new NotificationService();
            for (int i = 0; i < 15; i++)
            {
                service.SendNotification("Test", i.ToString(), $"Entity {i}", EntityOperation.CREATE);
            }

            var result = controller.GetNotifications();
            Assert.NotNull(result);
        }
    }
}

