using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class SchoolContextTests
    {
        [Fact]
        public void CanAddAndRetrieveStudent()
        {
            using var context = TestHelpers.CreateInMemoryContext();

            context.Students.Add(new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = DateTime.Now
            });
            context.SaveChanges();

            Assert.Single(context.Students);
            Assert.Equal("Test", context.Students.First().FirstMidName);
        }

        [Fact]
        public void CanAddAndRetrieveCourse()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedDepartments(context);

            context.Courses.Add(new Course
            {
                CourseID = 5000,
                Title = "Test Course",
                Credits = 3,
                DepartmentID = 1
            });
            context.SaveChanges();

            var course = context.Courses.Find(5000);
            Assert.NotNull(course);
            Assert.Equal("Test Course", course.Title);
        }

        [Fact]
        public void CanAddAndRetrieveDepartment()
        {
            using var context = TestHelpers.CreateInMemoryContext();

            context.Departments.Add(new Department
            {
                DepartmentID = 100,
                Name = "Test Dept",
                Budget = 50000,
                StartDate = DateTime.Parse("2020-01-01")
            });
            context.SaveChanges();

            var dept = context.Departments.Find(100);
            Assert.NotNull(dept);
            Assert.Equal("Test Dept", dept.Name);
        }

        [Fact]
        public void CanAddAndRetrieveInstructor()
        {
            using var context = TestHelpers.CreateInMemoryContext();

            context.Instructors.Add(new Instructor
            {
                FirstMidName = "Jane",
                LastName = "Doe",
                HireDate = DateTime.Parse("2015-06-15"),
                CourseAssignments = new List<CourseAssignment>()
            });
            context.SaveChanges();

            Assert.Single(context.Instructors);
            Assert.Equal("Jane", context.Instructors.First().FirstMidName);
        }

        [Fact]
        public void CanAddEnrollment()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedStudents(context);
            TestHelpers.SeedCourses(context);

            context.Enrollments.Add(new Enrollment
            {
                StudentID = 1,
                CourseID = 1050,
                Grade = Grade.A
            });
            context.SaveChanges();

            Assert.Single(context.Enrollments);
            Assert.Equal(Grade.A, context.Enrollments.First().Grade);
        }

        [Fact]
        public void CanAddCourseAssignment()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedInstructors(context);
            TestHelpers.SeedCourses(context);

            context.CourseAssignments.Add(new CourseAssignment
            {
                InstructorID = 10,
                CourseID = 1050
            });
            context.SaveChanges();

            Assert.Single(context.CourseAssignments);
        }

        [Fact]
        public void CanAddOfficeAssignment()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedInstructors(context);

            context.OfficeAssignments.Add(new OfficeAssignment
            {
                InstructorID = 10,
                Location = "Room 101"
            });
            context.SaveChanges();

            Assert.Single(context.OfficeAssignments);
            Assert.Equal("Room 101", context.OfficeAssignments.First().Location);
        }

        [Fact]
        public void CanAddNotification()
        {
            using var context = TestHelpers.CreateInMemoryContext();

            context.Notifications.Add(new Notification
            {
                EntityType = "Student",
                EntityId = "1",
                Operation = "CREATE",
                Message = "Student created",
                CreatedAt = DateTime.Now,
                CreatedBy = "System",
                IsRead = false
            });
            context.SaveChanges();

            Assert.Single(context.Notifications);
        }

        [Fact]
        public void StudentInheritsFromPerson()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedStudents(context);

            var person = context.People.First();
            Assert.IsType<Student>(person);
        }

        [Fact]
        public void InstructorInheritsFromPerson()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedInstructors(context);

            var people = context.People.ToList();
            Assert.Contains(people, p => p is Instructor);
        }

        [Fact]
        public void CourseAssignment_HasCompositeKey()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedInstructors(context);
            TestHelpers.SeedCourses(context);

            context.CourseAssignments.Add(new CourseAssignment { InstructorID = 10, CourseID = 1050 });
            context.SaveChanges();

            var assignment = context.CourseAssignments.Find(1050, 10);
            Assert.NotNull(assignment);
        }

        [Fact]
        public void DeleteStudent_RemovesFromDatabase()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedStudents(context);

            var student = context.Students.Find(1);
            context.Students.Remove(student);
            context.SaveChanges();

            Assert.Equal(2, context.Students.Count());
            Assert.Null(context.Students.Find(1));
        }

        [Fact]
        public void UpdateStudent_PersistsChanges()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            TestHelpers.SeedStudents(context);

            var student = context.Students.Find(1);
            student.FirstMidName = "Updated";
            context.SaveChanges();

            var updated = context.Students.Find(1);
            Assert.Equal("Updated", updated.FirstMidName);
        }
    }
}

